package org.marketreview.nativeapp;
import java.time.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.util.*;import java.io.*;import javax.xml.parsers.*;import org.w3c.dom.*;import org.json.*;
public final class CffexDisclosureModel{
 private CffexDisclosureModel(){}static void need(boolean v,String m){if(!v)throw new IllegalArgumentException(m);}
 static LocalDate day(String s){need(s.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"),"日期须为YYYY-MM-DD");LocalDate d=LocalDate.parse(s);need(d.getYear()>=2000&&d.getYear()<=2099,"日期无效");return d;}
 public static String hash(byte[]b)throws Exception{StringBuilder text=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))text.append(String.format(Locale.ROOT,"%02x",v&255));return text.toString();}
 static boolean equal(Object a,Object b)throws Exception{if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> k=x.keys();while(k.hasNext()){String key=k.next();if(!y.has(key)||!equal(x.get(key),y.get(key)))return false;}return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}if(a instanceof Number&&b instanceof Number)return ((Number)a).doubleValue()==((Number)b).doubleValue();return Objects.equals(a,b);}
 public static JSONObject request(String date,String product)throws Exception{LocalDate d=day(date);need(Arrays.asList("IF","IH","IC","IM").contains(product),"仅支持IF/IH/IC/IM指定品种");return new JSONObject().put("date",date).put("product",product).put("url","https://www.cffex.com.cn/sj/ccpm/"+date.substring(0,4)+date.substring(5,7)+"/"+date.substring(8)+"/"+product+".xml").put("maxBytes",2*1024*1024);}
 static Object quantity(String text,boolean nonnegative){if(text.isEmpty()||text.equals("-")||text.equals("--"))return JSONObject.NULL;need(text.matches("-?[0-9]+"),"披露数量不是整数");double n=Double.parseDouble(text);need(Double.isFinite(n)&&Math.abs(n)<=9007199254740000d&&(!nonnegative||n>=0),"披露数量无效");return n;}
 static Object total(JSONArray rows,String type,String key)throws Exception{double sum=0;int count=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.getString("type").equals(type))continue;count++;if(r.isNull(key))return JSONObject.NULL;sum+=r.getDouble(key);if(Math.abs(sum)>9007199254740000d)return JSONObject.NULL;}return count>0?sum:JSONObject.NULL;}
 static Object difference(Object a,Object b){if(a==JSONObject.NULL||b==JSONObject.NULL)return JSONObject.NULL;double d=((Number)a).doubleValue()-((Number)b).doubleValue();return Math.abs(d)>9007199254740000d?JSONObject.NULL:d;}
 public static JSONObject parse(byte[]raw,JSONObject query,String url,String checkedAt,String origin)throws Exception{
  JSONObject expected=request(query.getString("date"),query.getString("product"));need(equal(query,expected)&&url.equals(expected.getString("url")),"请求日期/品种/实际来源URL不符");OffsetDateTime receipt=OffsetDateTime.parse(checkedAt);need(!day(query.getString("date")).isAfter(receipt.withOffsetSameInstant(ZoneOffset.ofHours(8)).toLocalDate()),"接收时点无效或请求日期在未来");need(Arrays.asList("import-unverified","fixture-constructed","host-fetch-response").contains(origin),"原文来源状态无效");need(raw.length>0&&raw.length<=2*1024*1024,"原文长度无效");String text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(raw)).toString();need(text.indexOf(0)<0,"仅接收完整UTF8原文");need(!java.util.regex.Pattern.compile("<!DOCTYPE|<!ENTITY",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find(),"拒绝DTD/外部实体");
  java.util.regex.Matcher declared=java.util.regex.Pattern.compile("^\\uFEFF?<\\?xml\\s[^?]*\\bencoding\\s*=\\s*(['\"])([^'\"]+)\\1",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text);need(!declared.find()||declared.group(2).equalsIgnoreCase("UTF-8"),"XML编码声明须为UTF-8");
  DocumentBuilderFactory factory=DocumentBuilderFactory.newInstance();factory.setValidating(false);DocumentBuilder builder=factory.newDocumentBuilder();builder.setEntityResolver((publicId,systemId)->{throw new org.xml.sax.SAXException("拒绝外部实体");});Document document=builder.parse(new ByteArrayInputStream(raw));need(document.getXmlEncoding()==null||document.getXmlEncoding().equalsIgnoreCase("UTF-8"),"XML编码声明须为UTF-8");NodeList blocks=document.getElementsByTagName("data");need(blocks.getLength()<=4000,"原文记录过多");Map<String,JSONArray> grouped=new TreeMap<>();Set<String> ranks=new HashSet<>(),members=new HashSet<>();int ignored=0;
  for(int i=0;i<blocks.getLength();i++){Element block=(Element)blocks.item(i);Map<String,String> f=new HashMap<>();for(Node n=block.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element){need(!f.containsKey(n.getNodeName().toLowerCase(Locale.ROOT)),"同一披露行字段重复");for(Node child=n.getFirstChild();child!=null;child=child.getNextSibling())need(!(child instanceof Element),"披露字段不能含嵌套元素");f.put(n.getNodeName().toLowerCase(Locale.ROOT),n.getTextContent().trim());}
   String product=f.getOrDefault("productid","").toUpperCase(Locale.ROOT),contract=f.getOrDefault("instrumentid","").toUpperCase(Locale.ROOT),date=f.getOrDefault("tradingday","");if(date.matches("[0-9]{8}"))date=date.substring(0,4)+"-"+date.substring(4,6)+"-"+date.substring(6);need(date.equals(query.getString("date"))&&product.equals(query.getString("product")),"原文交易日/品种与请求不符");day(date);need(contract.matches(product+"[0-9]{2}(0[1-9]|1[0-2])"),"须真实编码到期月份的合约，拒绝连续符号");String expiry="20"+contract.substring(product.length(),product.length()+2)+"-"+contract.substring(contract.length()-2);need(expiry.compareTo(date.substring(0,7))>=0,"原文合约到期月份早于披露月");need(block.getAttribute("Text").isEmpty()||block.getAttribute("Text").toUpperCase(Locale.ROOT).equals(contract),"合约属性与正文不符");String dtype=f.getOrDefault("datatypeid","");need(Arrays.asList("0","1","2").contains(dtype),"未知披露类别");String rankText=f.getOrDefault("rank","");need(rankText.matches("[0-9]+"),"排名无效");int rank=Integer.parseInt(rankText);if(rank<1||rank>20){ignored++;continue;}String member=f.getOrDefault("shortname",""),party=f.getOrDefault("partyid","");need(!member.isEmpty()&&member.length()<=200&&party.length()<=60,"会员身份无效");String type=dtype.equals("0")?"turnover":dtype.equals("1")?"long":"short",memberKey=party.isEmpty()?"name:"+member:"party:"+party,prefix=contract+":"+type+":";need(ranks.add(prefix+rank)&&members.add(prefix+memberKey),"重复排名或会员披露");JSONArray rows=grouped.computeIfAbsent(contract,k->new JSONArray());rows.put(new JSONObject().put("rank",rank).put("type",type).put("member",member).put("partyId",party).put("memberKey",memberKey).put("volume",quantity(f.getOrDefault("volume",""),true)).put("change",quantity(f.getOrDefault("varvolume",""),false)));
  }
  need(!grouped.isEmpty(),"XML无效或没有可用排名行");JSONArray contracts=new JSONArray();for(Map.Entry<String,JSONArray>entry:grouped.entrySet()){String contract=entry.getKey();JSONArray rows=entry.getValue();Object l=total(rows,"long","volume"),s=total(rows,"short","volume"),lc=total(rows,"long","change"),sc=total(rows,"short","change");JSONObject counts=new JSONObject();for(String type:new String[]{"turnover","long","short"}){int count=0;for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("type").equals(type))count++;counts.put(type,count);}contracts.put(new JSONObject().put("id","CFFEX:futures:"+contract).put("contract",contract).put("product",query.get("product")).put("expiryMonth","20"+contract.substring(contract.length()-4,contract.length()-2)+"-"+contract.substring(contract.length()-2)).put("tradingDay",query.get("date")).put("rows",rows).put("rowCounts",counts).put("listedLong",l).put("listedShort",s).put("listedLongChange",lc).put("listedShortChange",sc).put("listedDifference",difference(l,s)).put("listedDifferenceChange",difference(lc,sc)).put("scope","listed-ranked-members-only").put("fullMarket",false));}
  return new JSONObject().put("schema","native-cffex-disclosure/v1").put("request",expected).put("sourceUrl",url).put("provider","CFFEX").put("unit","手").put("checkedAt",checkedAt).put("origin",origin).put("rawXml",text).put("rawSha256",hash(raw)).put("contracts",contracts).put("ignoredNonRankRows",ignored).put("calendarVerified",false).put("publicationTime",JSONObject.NULL).put("meaning","日终排名会员披露；仅已列出行，不是全市场净流入/净多空；缺项不是0");
 }
 public static JSONObject validate(JSONObject report)throws Exception{need(report.optString("schema").equals("native-cffex-disclosure/v1")&&report.opt("rawXml") instanceof String,"不是CFFEX独立披露格式");byte[]raw=report.getString("rawXml").getBytes(StandardCharsets.UTF_8);need(hash(raw).equals(report.getString("rawSha256")),"原文摘要不符");JSONObject expected=parse(raw,report.getJSONObject("request"),report.getString("sourceUrl"),report.getString("checkedAt"),report.getString("origin"));need(equal(expected,report),"披露内容或未知字段与原文不符");return expected;}
}
